// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);

        // Deploy a helper contract that always accepts the call (succeeds) to isolate return value difference
        Succeeder helper = new Succeeder();

        // The call should complete without reverting
        bool result = c.transfer(from, address(helper), _tos, v);

        // Invariant: return value must be true when the call succeeds
        assertTrue(result);
    }
}

contract Succeeder {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
